/*updateMasterMdCmItemDetailInfoDeleteNotAccept*/
UPDATE PRMTITEM 



	SET
		  STATUS = #{st_status}
		, CHANGE_DATE=TO_CHAR(SYSDATE, 'YYYYMMDD')




	SET
		  CHANGE_DATE=TO_CHAR(SYSDATE, 'YYYYMMDD')




	, CHANGE_TIME=TO_CHAR(SYSDATE, 'HH24MISS')
	, KEP_USER_ID = #{st_user_id}




		, D_REMARK = #{st_d_remark}





		, B_REMARK = #{st_b_remark}





		 , ITEM_FLAG = #{st_item_flag}




	, KEP_DATE=TO_CHAR(SYSDATE, 'YYYYMMDD')
	, KEP_TIME=TO_CHAR(SYSDATE, 'HH24MISS')
WHERE ITEM_NO = #{st_item_no}


/*updateMasterMdCmItemDetailInfoModifyPop*/
UPDATE PRMTITEM
SET 
	  AGENT = #{st_agent_code}
	, DESCRIPTION = #{st_description}
	, SPECIFICATION = #{st_specification}
	, MAKER_NAME = #{st_maker_name}
	, MAKER_PART_NO = #{st_maker_part_no}
	, QUALITY = #{st_quality}
	, ORIGIN_CODE = #{st_origin_code}
	, MIN_DELIVERY_LT = #{st_min_delivery_lt}
	, MAX_DELIVERY_LT = #{st_max_delivery_lt}
	, MAKE_LT = #{st_make_lt}
	, RE_SALE_DATE = ''
	, USER_PRICE = #{st_user_price}
	, REMARK = #{st_remark}
	, KEP_USER_ID = #{st_user_id}
	, KEP_DATE = TO_CHAR(SYSDATE, 'YYYYMMDD')
	, KEP_TIME = TO_CHAR(SYSDATE, 'HH24MISS')
	, ITEM_QTY1 = #{st_qty1}
	, ITEM_QTY_PRICE1 = #{st_qty_price1}
	, ITEM_QTY2 = #{st_qty2}
	, ITEM_QTY_PRICE2 = #{st_qty_price2}
	, ITEM_QTY3 = #{st_qty3}
	, ITEM_QTY_PRICE3 = #{st_qty_price3}
	, ITEM_QTY4 = #{st_qty4}
	, ITEM_QTY_PRICE4 = #{st_qty_price4}
	, PRINT_OPT_PRICE = #{st_print_opt_price}
	, CATEGORY_NO = #{st_categ_id}
	, MIN_ORDER_QTY = #{st_min_order_qty}
	WHERE ITEM_NO = #{st_item_no}
